            "easy2_desc": "그래서 연구진은 전체를 한 번에 보지 않고 좌표별로 쪼개서 확률을 추정하는 데이터 기반 프레임워크를 제안했는데요. 전부 다 섞어서 계산하는 대신 각 좌표의 확률만 따로 구했더니, 저장하고 계산해야 할 확률 데이터의 양이 엄청나게 줄어들었다는 거예요. 벤치마크 실험을 해 보니까 기존 방식보다 성능이 최대 25퍼센트포인트나 높아졌고, 필요한 메모리는 23배나 줄어들면서 속도도 훨씬 빨라졌다는 장점이 있거든요. 대신 좌표 간의 조건부 독립이나 리프시츠 상수를 미리 알고 있어야 한다는 조건이 붙는다는 점도 같이 기억해 둘 필요가 있습니다.",
