            "easy1_desc": "연구진은 대형 언어 모델(Large Language Model, LLM) 에이전트의 간접 프롬프트 주입(Indirect Prompt Injection, IPI) 취약점을 찾으려고 강화학습(Reinforcement Learning, RL) 기반 공격 기법인 RL-Hammer와 PISmith를 분석해 봤는데요. 높은 공격 성공률(Attack Success Rate, ASR)을 기록했음에도 불구하고, 그 공격들로 적대적 학습을 거쳐도 실제 방어력은 크게 높아지지 않았다는 사실을 발견했어요. 왜냐하면 공격 방식이 한쪽으로 쏠리는 모드 붕괴(Mode Collapse) 현상이 일어나서, 비슷한 공격만 반복해서 찾다 보니 방어력을 키우는 데는 도움이 되지 않았다는 말이에요. 쉽게 말하면, 공격은 잘 찾았지만 정작 방어를 단단하게 만드는 데는 한계가 있었다는 셈이에요.",
