            "easy1_desc": "언어 모델은 연속된 단어 묶음인 n-gram 임베딩 표를 써서 계산 부담을 줄이면서 용량을 키울 수 있는데요, 최근에는 층마다 따로 표를 두다 보니 메모리가 많이 들고 층끼리 배운 걸 나누지 못한다는 단점이 있거든요. 그렇다고 표를 딱 하나만 쓰면 모든 층이 똑같은 임베딩만 보게 되면서 층별 성향을 살릴 수 없고 성능도 떨어진다는 말이에요. 쉽게 말하면, 따로 쓰자니 메모리가 낭비되고 같이 쓰자니 각 층에 안 맞았다는 겁니다.",
