            "easy2_desc": "그래서 연구진은 그림에 결함이 있다고 말해주지 않은 채 이름만 알려줬더니, 기준을 통과한 진단 비율이 4.3%에서 20.4%로 올라갔다는 건데요. 렌더링된 그림에서만 모순이 드러나는 경우 텍스트만 보는 방식으로는 진단을 하나도 못 해냈지만, 이름을 알려주고 렌더링된 페이지를 함께 보여주니 15.8%까지 올라갔다는 겁니다. 서류나 중심성에 따라 확인할 그림을 고르게 해봐도 4.8%에 머물렀다는 단점이 있는데, 장점은 무엇을 검증해야 할지 정해주는 것만으로도 성능이 꽤 달라진다는 걸 확인했다는 거예요. 쉽게 말하면, 어디를 볼지 직접 고르는 과정 자체가 어렵고 핵심이라는 말입니다.",
