            "easy1_desc": "기존의 에이전트형 멀티모달 거대언어모델(MLLM)은 이미지를 분석할 때 추론과 확대 도구 호출을 반복하는 방식을 쓰는데요, 이 과정이 순차적으로 이루어지다 보니 속도가 느리다는 단점이 있어요. 게다가 모델이 내놓은 답이 얼마나 정확한지 알려주는 신뢰도 점수도 없어서 답을 그대로 믿기 어려운 상황이었거든요. 기존 연구들은 답을 미리 예측해 보기도 했지만, 여전히 느린 반복 구조를 벗어나지 못하거나 자신감 있게 틀린 답을 내놓는 문제가 있었던 겁니다.",
            "easy2_title": "답 대신 관찰 결과를 미리 예측해서 속도와 정확도를 모두 잡았어요",
