            "easy1_desc": "자율형 인공지능 에이전트(Autonomous AI agents)가 경험을 바탕으로 스스로 프롬프트나 기억 같은 도구들을 고쳐나가는 재귀적 자기 개선(Recursive self-improvement) 방식을 써봤는데요. 외부에서 채점해 주는 사람 없이 혼자 반성하고 점수를 매기다 보니까, 새로 망가진 부분과 원래 못 풀던 문제를 헷갈려 한다는 거예요. 그 때문에 실력이 떨어지거나 아예 옛날 기술을 까먹고 기억 공간만 낭비하는 문제가 생겼다는 말입니다.",
