            "easy1_desc": "온폴리시 증류(On-policy distillation, OPD)라는 방식으로 대형 언어 모델 에이전트에 전문 능력을 옮길 때 다른 영역의 상호작용에 어떤 영향이 생기는지 분명하지 않았는데요. 연구진이 수학과 ALFWorld, 그리고 타우투벤치(tau^2-bench) 영역에서 추론과 행동, 관찰 수집 방식이 어떻게 바뀌는지 조사해 봤습니다. 그 결과 일반 추론 지도(General-reasoning supervision)를 쓰면 수학 도구 시도 횟수가 70.4%에서 14.4%로 줄어드는 대신 정확도는 16.7%에서 38.0%로 높아지는 것으로 나타났습니다. 코드 인터프리터(Code-interpreter) 지도를 쓰면 가정용 행동과 소매 관련 질의 능력이 나아진다는 겁니다.",
            "easy2_title": "영역을 잘못 섞었을 때의 문제를 줄일 방법을 찾아봤습니다",
            "easy2_desc": "반면에 ALFWorld 지도를 썼더니 타우투벤치 정확도가 41.5%에서 6.6%로 떨어졌는데요, 사용자 정보 의존성을 어기는 잦은 도구 호출이 늘어났기 때문이라는 말이에요. 그래서 연구진은 원천 도메인 학습 궤적만 써서 부정적 전이를 해결하려고 교사 모델의 선호 변화를 이용한 선택적 온폴리시 증류(Selective OPD)를 시도해 봤습니다. 상위 95% 위치를 남겨뒀더니 타우투벤치 정확도가 11.5%에서 29.9%로 높아졌는데, 대신 원천 학습과의 사이에서 절충안이 생긴다는 단점도 있다는 겁니다. 쉽게 말하면, 다른 영역의 지식을 무작정 섞으면 성능이 망가지지만 교사 모델의 선호를 골라 쓰면 어느 정도 보완할 수 있다는 셈이에요.",
